export function findQuestionChapter(qid: string, defaultCh = 1): number {
  if (QUESTION_CHAPTERS[qid] !== undefined) {
    return QUESTION_CHAPTERS[qid];
  }
  const m = /^ch(\d+)-/i.exec(qid);
  if (m) {
    const n = parseInt(m[1], 10);
    if (!isNaN(n) && n > 0) return n;
  }
  return defaultCh;
}
